(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.012-t*0.15)*8+Math.cos((y+w1y)*0.01+t*0.18)*6;
  const w2y = Math.cos((y+w1y)*0.013+t*0.2)*8+Math.sin((x+w1x)*0.011-t*0.16)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.11,2.1],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75)*55,0.05,2.8]
  ];
  let aS=0,iS=0,aS2=0,iS2=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS2+=Math.cos(d*f*1.3+t*sp*0.8+0.7);iS2+=Math.cos(d*f*0.5-t*sp*0.4+2.1);
  }
  const act=aS/8,inh=iS/8,act2=aS2/8,inh2=iS2/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.06*Math.cos(t*0.1)+sy*0.05*Math.sin(t*0.13)+t*1.7)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    +Math.sin(dist*0.07-ang*2+t*0.9)*0.2+Math.sin(dist*0.03+ang*6-t*2.1)*0.15;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const cell2=Math.tanh((Math.cos(sx*0.12+t*0.3)*Math.cos(sy*0.12-t*0.2)+Math.sin((sx-sy)*0.08-t*0.7)*0.4)*1.3)*0.2;
  const r1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const r2=Math.tanh((act2-inh2*0.6+bg*0.2-spiral*0.5+cell2)*1.8);
  const cross=r1*r2*0.6;
  const blend=r1*0.5+r2*0.25+cross*0.15+cell*0.1;
  const v=blend*0.5+0.5;
  const pal=[[5,12,45],[12,45,85],[18,95,120],[25,155,145],[60,190,130],
    [180,195,80],[220,160,60],[210,100,65],[175,55,75],[120,30,60],
    [65,18,48],[20,10,38],[5,12,45]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.75+Math.sin(r1*Math.PI)*0.15+Math.cos(r2*Math.PI)*0.1;
  const edge=Math.abs(r1)>0.7?1.2:Math.abs(r2)>0.6?1.1:1.0;
  const glow=Math.max(0,(Math.abs(r1)-0.5)*0.8)+Math.max(0,(Math.abs(r2)-0.4)*0.4);
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*15)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*8)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*20)|0)
  ];
}
